    <script>
        // JavaScript for Interactive Features

        // 1. 图片画廊交互
        const thumbnails = document.querySelectorAll('.thumbnail');
        const mainImage = document.getElementById('media_image_image');

        thumbnails.forEach(thumb => {
            thumb.addEventListener('click', function() {
                // 更新主图源
                const fullSizeSrc = this.getAttribute('data-full');
                mainImage.src = fullSizeSrc;
                mainImage.alt = this.alt;

                // 更新激活状态
                thumbnails.forEach(t => t.classList.remove('active'));
                this.classList.add('active');
            });
        });

        // 2. 表单提交处理
        const contactForm = document.getElementById('contact_form');
        contactForm.addEventListener('submit', function(event) {
            event.preventDefault(); // 阻止默认提交（演示用）

            // 获取表单数据
            const name = document.getElementById('contact_name').value;
            const email = document.getElementById('contact_email').value;
            const message = document.getElementById('contact_message').value;

            // 简单验证
            if (name && email && message) {
                // 在实际应用中，这里会发送数据到服务器
                alert(`Thank you, ${name}! Your message has been received (Demo). We'll get back to you at ${email}.`);
                // 重置表单
                contactForm.reset();
            } else {
                alert('Please fill in all required fields.');
            }
        });

        // 3. 音频/视频控制台日志（演示交互）
        const audioPlayer = document.getElementById('media_audio_track');
        const videoPlayer = document.getElementById('media_video_video');

        audioPlayer.addEventListener('play', () => {
            console.log('Relaxing cat purrs audio started playing.');
        });

        videoPlayer.addEventListener('play', () => {
            console.log('Playful kitten video started playing.');
        });

        // 4. 简单样式交互增强：按钮点击反馈
        const submitButton = document.querySelector('[data-target="form-submit"]');
        submitButton.addEventListener('click', function() {
            this.style.transform = 'scale(0.98)';
            setTimeout(() => {
                this.style.transform = 'scale(1)';
            }, 150);
        });
    </script>
</body>
</html>
